-- Name: validaciones_identidad; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.validaciones_identidad (
    id integer NOT NULL,
    sesion_id character varying(80) NOT NULL,
    numero_whatsapp character varying(20) NOT NULL,
    cedula character varying(15),
    cedula_ingresada_en timestamp without time zone,
    anverso_recibido_en timestamp without time zone,
    reverso_recibido_en timestamp without time zone,
    ocr_vs_sistema_resultado character varying(20) DEFAULT 'pendiente'::character varying,
    ocr_vs_sistema_detalle jsonb,
    codigo_dactilar_validado boolean DEFAULT false,
    correo character varying(150),
    correo_verificado boolean DEFAULT false,
    otp_codigo character varying(6),
    otp_expira_en timestamp without time zone,
    otp_intentos integer DEFAULT 0,
    estado_kyc character varying(30) DEFAULT 'iniciado'::character varying,
    intentos_fallidos_comparacion integer DEFAULT 0,
    derivado_revision boolean DEFAULT false,
    actualizado_en timestamp without time zone DEFAULT now()
);


