--
-- Name: vista_eventos_con_tiempos; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_eventos_con_tiempos AS
 SELECT eventos_interaccion.id,
    eventos_interaccion.sesion_id,
    eventos_interaccion.numero_whatsapp,
    eventos_interaccion.fecha_evento,
    eventos_interaccion.paso,
    eventos_interaccion.estado_conversacion,
    eventos_interaccion.intentos_comprobante,
    eventos_interaccion.cedula,
    eventos_interaccion.tipo_comprobante,
    eventos_interaccion.duplicado,
    eventos_interaccion.opcion_ocr,
    eventos_interaccion.monto_esperado,
    eventos_interaccion.deuda_total,
    eventos_interaccion.datos_adicionales,
    EXTRACT(epoch FROM (eventos_interaccion.fecha_evento - lag(eventos_interaccion.fecha_evento) OVER (PARTITION BY eventos_interaccion.sesion_id ORDER BY eventos_interaccion.fecha_evento))) AS segundos_desde_evento_anterior
   FROM public.eventos_interaccion;


--
-- Name: vista_identidad_clientes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_identidad_clientes AS
 SELECT d.id AS documento_id,
    d.fecha_hora,
    d.sesion_id,
    d.numero_whatsapp,
    d.cedula_ingresada,
    d.lado,
    d.nombre_archivo,
    d.ruta_imagen,
    d.media_id,
    d.cedula_ocr,
    d.nombres,
    d.apellidos,
    d.calidad_lectura,
    d.ocr_confianza,
    d.ocr_valido,
    d.coincide,
    v.estado_kyc,
    v.correo,
    v.correo_verificado,
    v.actualizado_en,
    ( SELECT o.resultado
           FROM public.otp_verificaciones o
          WHERE ((o.sesion_id)::text = (d.sesion_id)::text)
          ORDER BY o.creado_en DESC
         LIMIT 1) AS ultimo_resultado_otp
   FROM (public.documentos_identidad d
     LEFT JOIN public.validaciones_identidad v ON (((v.sesion_id)::text = (d.sesion_id)::text)));


--
-- Name: VIEW vista_identidad_clientes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.vista_identidad_clientes IS 'Consulta consolidada de documentos, validacion de identidad y resultado OTP; no expone codigos OTP.';


--
-- Name: vista_interaccion_completa; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_interaccion_completa AS
 SELECT s.sesion_id,
    s.numero_whatsapp,
    c.nombre,
    s.bot,
    s.intencion,
    s.estado_sesion,
    s.resultado,
    s.inicio,
    s.fin,
    EXTRACT(epoch FROM (s.fin - s.inicio)) AS duracion_segundos,
    s.intentos_comprobante,
    ( SELECT count(*) AS count
           FROM public.eventos_interaccion e
          WHERE ((e.sesion_id)::text = (s.sesion_id)::text)) AS total_eventos,
    ( SELECT count(*) AS count
           FROM public.eventos_interaccion e
          WHERE (((e.sesion_id)::text = (s.sesion_id)::text) AND ((e.paso)::text = ANY ((ARRAY['cedula_invalida'::character varying, 'comprobante_duplicado'::character varying, 'ocr_ilegible'::character varying, 'monto_no_coincide'::character varying])::text[])))) AS eventos_friccion,
    cp.numero_transaccion,
    cp.score_confianza,
    di.cedula_ocr
   FROM (((public.sesiones s
     JOIN public.clientes c ON (((c.numero_whatsapp)::text = (s.numero_whatsapp)::text)))
     LEFT JOIN public.comprobantes cp ON (((cp.sesion_id)::text = (s.sesion_id)::text)))
     LEFT JOIN public.documentos_identidad di ON (((di.sesion_id)::text = (s.sesion_id)::text)));


--
-- Name: vista_kyc_completo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vista_kyc_completo AS
 SELECT v.id,
    v.sesion_id,
    v.numero_whatsapp,
    v.cedula,
    v.estado_kyc,
    v.ocr_vs_sistema_resultado,
    v.intentos_fallidos_comparacion,
    v.derivado_revision,
    v.codigo_dactilar_validado,
    v.correo,
    v.correo_verificado,
    v.actualizado_en,
    s.bot,
    s.intencion,
    s.estado_sesion
   FROM (public.validaciones_identidad v
     LEFT JOIN public.sesiones s ON (((s.sesion_id)::text = (v.sesion_id)::text)));


